shopify-dash:
@keyframes shopify-dash { 
  0% { stroke-dashoffset: 280px; }
  50% { stroke-dashoffset: 75px; transform: rotate(135deg); }
  100% { stroke-dashoffset: 280px; transform: rotate(450deg); }
}

translateAnnouncementSlideIn:
@keyframes translateAnnouncementSlideIn { 
  0% { opacity: 0; transform: translate(var(--announcement-translate-from)); }
  100% { opacity: 1; transform: translate(0px); }
}

translateAnnouncementSlideOut:
@keyframes translateAnnouncementSlideOut { 
  0% { opacity: 1; transform: translate(0px); }
  100% { opacity: 0; transform: translate(var(--announcement-translate-to)); }
}

animateAmbient:
@keyframes animateAmbient { 
  0% { transform: rotate(0deg) translate(1em) rotate(0deg) scale(1.2); }
  100% { transform: rotate(360deg) translate(1em) rotate(-360deg) scale(1.2); }
}

slideIn:
@keyframes slideIn { 
  0% { transform: translateY(2rem); opacity: 0.01; }
  100% { transform: translateY(0px); opacity: 1; }
}

glowAnimation:
@keyframes glowAnimation { 
  0% { filter: blur(0px); opacity: 0; text-shadow: none; }
  100% { filter: blur(4px); opacity: 1; text-shadow: rgb(189, 134, 16) 0px 0px 25px; }
}

fb_transform:
@keyframes fb_transform { 
  0% { opacity: 0; transform: scale(0.95); }
  100% { opacity: 1; transform: scale(1); }
}

affirm_logo_listener:
@keyframes affirm_logo_listener { 
  0% { outline: rgba(0, 0, 0, 0) solid 1px; }
  100% { outline: rgba(0, 0, 0, 0) solid 0px; }
}

affirm_asset_listener:
@keyframes affirm_asset_listener { 
  0% { outline: rgba(0, 0, 0, 0) solid 1px; }
  100% { outline: rgba(0, 0, 0, 0) solid 0px; }
}

affirmFadeIn:
@keyframes affirmFadeIn { 
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

klaviyo-slideinleft:
@keyframes klaviyo-slideinleft { 
  0% { transform: translate3d(-100%, 0px, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-slideinright:
@keyframes klaviyo-slideinright { 
  0% { transform: translate3d(100%, 0px, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-slideinup:
@keyframes klaviyo-slideinup { 
  0% { transform: translate3d(0px, -100%, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-slideindown:
@keyframes klaviyo-slideindown { 
  0% { transform: translate3d(0px, 100%, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-fadeinup:
@keyframes klaviyo-fadeinup { 
  0% { opacity: 0; transform: translate3d(0px, 10%, 0px); visibility: visible; }
  100% { opacity: 1; transform: translate3d(0px, 0px, 0px); }
}

klaviyo-slideintopleft:
@keyframes klaviyo-slideintopleft { 
  0% { transform: translate3d(-100%, -100%, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-slideintopright:
@keyframes klaviyo-slideintopright { 
  0% { transform: translate3d(100%, -100%, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-slideinbottomright:
@keyframes klaviyo-slideinbottomright { 
  0% { transform: translate3d(100%, 100%, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-slideinbottomleft:
@keyframes klaviyo-slideinbottomleft { 
  0% { transform: translate3d(-100%, 100%, 0px); visibility: visible; }
  100% { transform: translate3d(0px, 0px, 0px); }
}

klaviyo-heartbeat:
@keyframes klaviyo-heartbeat { 
  0% { transform: scale(1); }
  14% { transform: scale(1.3); }
  28% { transform: scale(1); }
  42% { transform: scale(1.3); }
  70% { transform: scale(1); }
}

klaviyo-pulse:
@keyframes klaviyo-pulse { 
  0% { transform: scale3d(1, 1, 1); }
  50% { transform: scale3d(1.1, 1.1, 1.1); }
  100% { transform: scale3d(1, 1, 1); }
}

klaviyo-flipTop:
@keyframes klaviyo-flipTop { 
  0% { transform: rotateX(0deg); z-index: 2; }
  0%, 99% { opacity: 0.99; }
  100% { transform: rotateX(-90deg); opacity: 0; }
}

klaviyo-flipBottom:
@keyframes klaviyo-flipBottom { 
  0%, 50% { z-index: -1; transform: rotateX(90deg); opacity: 0; }
  51% { opacity: 0.99; }
  100% { opacity: 0.99; transform: rotateX(0deg); z-index: 5; }
}

dash:
@keyframes dash { 
  0% { stroke-dashoffset: 280; }
  50% { stroke-dashoffset: 75; transform: rotate(135deg); }
  100% { stroke-dashoffset: 280; transform: rotate(450deg); }
}

animateLocalization:
@keyframes animateLocalization { 
  0% { opacity: 0; transform: translateY(0px); }
  100% { opacity: 1; transform: translateY(-1rem); }
}
